import{_ as a,c as i,o as t,a2 as e}from"./chunks/framework.PGES7OoM.js";const c=JSON.parse('{"title":"estimatePortalDeposit","description":"Estimate a portal deposit that shields in place.","frontmatter":{"editLink":false,"rawMarkdown":"# estimatePortalDeposit\\n\\nEstimate a portal deposit that shields in place. Mirrors Vault.portalShield:\\ngross - floor(gross * depositFee / 10000) - pendingNoteCommitment - portalDeployment.\\nBridge routing/reimbursement is service-owned and must be quoted separately;\\nthis action deliberately does not substitute withdrawal fees or guess a destination.\\n\\n## Import\\n\\n```ts\\nimport { estimatePortalDeposit } from \\"@0xcurvy/curvy-sdk/actions\\";\\n```\\n\\n## Usage\\n\\n```ts\\nconst result = await estimatePortalDeposit({ networkSlug, token, amount, config });\\n```\\n\\n## Signature\\n\\n```ts\\nfunction estimatePortalDeposit(parameters: EstimatePortalDepositParameters): Promise<PortalDepositEstimate>\\n```\\n\\n## Returns\\n\\n`Promise<PortalDepositEstimate>`\\n\\nThe action resolves or returns the value shown in the signature.\\n\\n## Parameters\\n\\n### `networkSlug`\\n\\n- **Type:** `string`\\n- **Required:** yes\\n\\nThe network whose vault fees should be applied, by slug.\\n\\n```ts\\nconst result = await estimatePortalDeposit({\\n  networkSlug, // [!code focus]\\n  token,\\n  amount,\\n});\\n```\\n\\n### `token`\\n\\n- **Type:** `bigint`\\n- **Required:** yes\\n\\nThe vault token id of the deposited currency.\\n\\n```ts\\nconst result = await estimatePortalDeposit({\\n  networkSlug,\\n  token, // [!code focus]\\n  amount,\\n});\\n```\\n\\n### `amount`\\n\\n- **Type:** `bigint`\\n- **Required:** yes\\n\\nThe gross deposit amount in the vault token\'s base units.\\n\\n```ts\\nconst result = await estimatePortalDeposit({\\n  networkSlug,\\n  token,\\n  amount, // [!code focus]\\n});\\n```\\n\\n### `signal`\\n\\n- **Type:** `AbortSignal`\\n- **Required:** no\\n\\nAborts the fee reads.\\n\\n```ts\\nconst result = await estimatePortalDeposit({\\n  networkSlug,\\n  token,\\n  amount,\\n  signal, // [!code focus]\\n});\\n```\\n\\n### `config`\\n\\n- **Type:** `CurvyConfig`\\n- **Required:** no\\n\\nCurvy config to use. Defaults to the ambient config.\\n\\n```ts\\nconst result = await estimatePortalDeposit({\\n  networkSlug,\\n  token,\\n  amount,\\n  config, // [!code focus]\\n});\\n```\\n\\n## Errors\\n\\nErrors from config resolution and the underlying SDK operation are propagated to the caller.\\n\\n## Related\\n\\n- [Interacting with assets guide](/for-programmers/interacting-with-assets)\\n\\n## Source\\n\\n[packages/@0xcurvy/sdk/src/actions/planner/estimatePortalDeposit.ts](https://github.com/0xCurvy/curvy-monorepo/blob/main/packages/@0xcurvy/sdk/src/actions/planner/estimatePortalDeposit.ts)\\n","rawMarkdownPath":"/_raw/sdk/actions/planner/estimatePortalDeposit.md","rawMarkdownTitle":"estimatePortalDeposit","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/actions/planner/estimatePortalDeposit.md"},"headers":[],"params":{"sdkReferenceKind":"action","category":"planner","action":"estimatePortalDeposit"},"relativePath":"sdk/actions/planner/estimatePortalDeposit.md","filePath":"sdk/actions/[category]/[action].md","lastUpdated":1786448401000}'),n={name:"sdk/actions/planner/estimatePortalDeposit.md"};function l(o,s,r,p,h,k){return t(),i("div",null,[...s[0]||(s[0]=[e("",38)])])}const g=a(n,[["render",l]]);export{c as __pageData,g as default};
